{
  "packet_id": "H6-T04-3",
  "claims": [
    {
      "claim_id": "C001",
      "fields": ["state"],
      "component": {
        "component_id": "C001.component",
        "value": "Retain competing explanations for non-publication, including setup confusion, unavailable team information, intentional waiting, exploratory accounts and unobserved technical failures.",
        "scope": "Candidate explanations for the account-creation-to-first-publication path; none is established by being listed.",
        "provenance": {
          "refs": [{"source_id": "P002", "role": "SUPPORT"}, {"source_id": "P001", "role": "CONTEXT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P002 supplies the competing candidates; P001 identifies the process under consideration."
        }
      }
    },
    {
      "claim_id": "C002",
      "fields": ["state", "inference"],
      "component": {
        "component_id": "C002.component",
        "value": "Multiple mechanisms may coexist, so mixed explanations should be retained where appropriate.",
        "scope": "Possibility of mixed causes, not a finding that multiple causes are present.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}, {"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The spans state coexistence and its corresponding implication for retaining explanations."
        }
      }
    },
    {
      "claim_id": "C003",
      "fields": ["state"],
      "component": {
        "component_id": "C003.component",
        "value": "The eight interviews suggest candidate explanations.",
        "scope": "Candidate generation from the reported interviews, without establishing population frequency.",
        "provenance": {
          "refs": [{"source_id": "P004", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly assigns the interviews a candidate-generating role and limits their prevalence implications."
        }
      }
    },
    {
      "claim_id": "C004",
      "fields": ["state", "limit"],
      "component": {
        "component_id": "C004.component",
        "value": "The eight interviews do not establish or estimate the population prevalence of the candidate explanations.",
        "scope": "Prevalence claims based on these eight interviews.",
        "provenance": {
          "refs": [{"source_id": "P004", "role": "SUPPORT"}, {"source_id": "P031", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "Both spans express the same prevalence limitation."
        }
      }
    },
    {
      "claim_id": "C005",
      "fields": ["state"],
      "component": {
        "component_id": "C005.component",
        "value": "Existing event records omit offline preparation.",
