          "refs": [{"source_id": "P004", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The omission is explicitly stated."
        }
      }
    },
    {
      "claim_id": "C006",
      "fields": ["state"],
      "component": {
        "component_id": "C006.component",
        "value": "First publication is assumed to represent useful activation only provisionally.",
