        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly states the assumption and its provisional status."
        }
      }
    },
    {
      "claim_id": "C007",
      "fields": ["state"],
      "component": {
        "component_id": "C007.component",
        "value": "Whether interviewed accounts actually intended to publish must be checked.",
