          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly requires checking this assumption."
        }
      }
    },
    {
      "claim_id": "C008",
      "fields": ["operation"],
      "component": {
        "component_id": "C008.component",
        "value": "Comparisons of account-level event sequences should use accounts of similar age.",
        "scope": "Inspection of invitation, draft-save and publication sequences.",
        "provenance": {
          "refs": [{"source_id": "P006", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The age-comparability requirement is explicit."
