    },
    {
      "claim_id": "C011",
      "fields": ["operation"],
      "component": {
        "component_id": "C011.component",
        "value": "Where feasible, evidence gathering should include observation of a realistic setup attempt using information the customer already possesses.",
        "scope": "A proposed observation method conditional on feasibility, not a completed observation.",
        "provenance": {
          "refs": [{"source_id": "P008", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states the proposed method, realism condition and available-information restriction."
        }
      }
    },
    {
      "claim_id": "C012",
      "fields": ["operation"],
      "component": {
        "component_id": "C012.component",
        "value": "Evidence gathering should seek observations against each explanation as well as observations supporting it.",
        "scope": "Each retained candidate explanation.",
        "provenance": {
          "refs": [{"source_id": "P009", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The two-sided evidence-seeking requirement is explicit."
