        "provenance": {
          "refs": [{"source_id": "P010", "role": "SUPPORT"}, {"source_id": "P012", "role": "CONTEXT"}],
          "support_status": "SUFFICIENT",
          "rationale": "P010 explicitly supplies the rule; P012 identifies the separate branch that leaves its outer scope ambiguous."
        }
      }
    },
    {
      "claim_id": "C015",
      "fields": ["operation"],
      "component": {
        "component_id": "C015.component",
        "value": "Observed comprehension failures provide a proposed reason to select clearer guidance as the narrowly scoped change.",
        "scope": "An illustrative intervention choice conditional on evidence of an actionable obstacle; effectiveness is not established.",
        "provenance": {
          "refs": [{"source_id": "P010", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly links this obstacle to this example intervention."
        }
      }
    },
    {
      "claim_id": "C016",
      "fields": ["operation"],
      "component": {
        "component_id": "C016.component",
        "value": "Uncertainty about required team information provides a proposed reason to select a preparation checklist.",
        "scope": "An illustrative narrowly scoped intervention conditional on evidence of an actionable obstacle; effectiveness is not established.",
        "provenance": {
          "refs": [{"source_id": "P010", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly links information uncertainty to the checklist example."
        }
      }
    },
    {
      "claim_id": "C017",
      "fields": ["operation"],
      "component": {
        "component_id": "C017.component",
        "value": "If evidence supports intentional waiting, test an optional reminder near the intended roster date.",
        "scope": "The intentional-waiting branch; a proposed test, not an established reminder benefit.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The conditional recommendation, optionality and timing are explicit."
        }
      }
    },
    {
      "claim_id": "C018",
      "fields": ["operation"],
      "component": {
        "component_id": "C018.component",
        "value": "When evidence supports intentional waiting, a need to simplify setup should not be assumed.",
        "scope": "A restriction on interpretation in the intentional-waiting branch, not a conclusion that simplification could never help.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly rejects assuming a setup-simplification need under this condition."
        }
      }
    },
    {
      "claim_id": "C019",
      "fields": ["operation"],
      "component": {
        "component_id": "C019.component",
        "value": "If evidence fails to distinguish explanations, use the release slot for a minimal diagnostic prompt or event improvement.",
